import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.CZo9GF0W.js";const u=JSON.parse('{"title":"Amazon RDS and Aurora","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/rds.md","filePath":"recipes/rds.md","lastUpdated":1789060268000}'),i={name:"recipes/rds.md"};function o(n,e,d,h,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="amazon-rds-and-aurora" tabindex="-1">Amazon RDS and Aurora <a class="header-anchor" href="#amazon-rds-and-aurora" aria-label="Permalink to &quot;Amazon RDS and Aurora&quot;">​</a></h1><p>Works for RDS and Aurora PostgreSQL, MySQL and SQL Server. The differences are the port and the driver.</p><h2 id="reachability-first" tabindex="-1">Reachability first <a class="header-anchor" href="#reachability-first" aria-label="Permalink to &quot;Reachability first&quot;">​</a></h2><p>An RDS instance is in a VPC. It is reachable from something inside that VPC, or from an address you have allowed into its security group. So before anything else, decide which machine is connecting:</p><ul><li><strong>A VPC bastion</strong>, with VS Code attached over Remote-SSH. Pitta then runs on the bastion, the endpoint resolves privately, and no tunnel is needed. This is the simplest arrangement and the one to reach for.</li><li><strong>Your laptop, through a bastion</strong>, using <a href="./ssh">Pitta&#39;s SSH tunnel</a>.</li><li><strong>A publicly accessible instance</strong>, with your address in the security group. Fine for a scratch database; think twice for anything else.</li></ul><p>Under Remote-SSH the address in the security group must be the <strong>remote&#39;s</strong> egress address, not your laptop&#39;s.</p><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to &quot;TLS&quot;">​</a></h2><p>RDS presents a certificate signed by an Amazon CA that your system does not trust by default. Do not turn verification off; point at the bundle.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.certs/rds-global-bundle.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://truststore.pki.rds.amazonaws.com/global/global-bundle.pem</span></span></code></pre></div><p>There are per-region bundles too; the global one covers every region and is simpler to distribute.</p><h2 id="the-profile" tabindex="-1">The profile <a class="header-anchor" href="#the-profile" aria-label="Permalink to &quot;The profile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Host</td><td><code>orders.abc123.eu-west-1.rds.amazonaws.com</code> — the writer endpoint, or the reader endpoint for a read-only profile</td></tr><tr><td>Port</td><td>5432 · MySQL 3306 · SQL Server 1433</td></tr><tr><td>Database</td><td>your database name — <strong>not</strong> <code>postgres</code> on Aurora unless that is really it</td></tr><tr><td>User</td><td>the master user, or better, a scoped one</td></tr><tr><td>SSL mode</td><td><code>verify-full</code></td></tr><tr><td>CA certificate</td><td><code>~/.certs/rds-global-bundle.pem</code></td></tr><tr><td>Environment</td><td><code>prod</code>, if it is</td></tr><tr><td>Read-only</td><td>tick it for a reader-endpoint profile</td></tr></tbody></table><p><code>verify-full</code> also checks the hostname, so connect through the endpoint name rather than through an IP address.</p><h2 id="aurora-reader-endpoints" tabindex="-1">Aurora reader endpoints <a class="header-anchor" href="#aurora-reader-endpoints" aria-label="Permalink to &quot;Aurora reader endpoints&quot;">​</a></h2><p>Make two profiles: the cluster (writer) endpoint tagged <code>prod</code>, and the reader endpoint tagged <code>prod</code> <strong>and</strong> marked read-only. The reader profile then refuses writes in Pitta as well as at the server, and the tree shows plainly which one you are in.</p><h2 id="iam-authentication" tabindex="-1">IAM authentication <a class="header-anchor" href="#iam-authentication" aria-label="Permalink to &quot;IAM authentication&quot;">​</a></h2><p>RDS IAM tokens are generated per connection and expire after 15 minutes, so they cannot be stored. Use <code>{ &quot;kind&quot;: &quot;prompt&quot; }</code> and paste a freshly generated token:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aws</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rds</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate-db-auth-token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --hostname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orders.abc123.eu-west-1.rds.amazonaws.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5432</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --region</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eu-west-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --username</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analyst</span></span></code></pre></div><p>The token is used as the password. TLS is mandatory for IAM authentication, which <code>verify-full</code> already satisfies.</p><h2 id="rds-proxy" tabindex="-1">RDS Proxy <a class="header-anchor" href="#rds-proxy" aria-label="Permalink to &quot;RDS Proxy&quot;">​</a></h2><p>Connect to the proxy&#39;s endpoint on the database&#39;s usual port, with the proxy&#39;s own certificate chain — the same Amazon bundle covers it. The proxy multiplexes connections, so session-scoped state (temporary tables, <code>SET</code> that outlives a statement, advisory locks) may not be pinned to your session. Prefer the instance endpoint for interactive work and leave the proxy to your application.</p><h2 id="things-that-look-like-bugs" tabindex="-1">Things that look like bugs <a class="header-anchor" href="#things-that-look-like-bugs" aria-label="Permalink to &quot;Things that look like bugs&quot;">​</a></h2><ul><li><strong>Timeout with no error.</strong> Almost always the security group. A rejected TCP connection times out rather than refusing.</li><li><strong><code>no pg_hba.conf entry … SSL off</code>.</strong> The instance requires TLS (<code>rds.force_ssl</code>) and the profile has it disabled.</li><li><strong>Certificate verification fails after years of working.</strong> Amazon rotates its CAs; re-download the bundle.</li></ul>`,23)])])}const k=t(i,[["render",o]]);export{u as __pageData,k as default};
